    unordered_map<char, Trie*> children;
    bool isEnd = false;

    void insert(string word) {
        Trie* node = this;
        for (char c : word) {
            if (!node->children.count(c)) node->children[c] = new Trie();    // create as needed
            node = node->children[c];
        }
        node->isEnd = true;
    }

